from pathlib import Path
from html import escape as E
import json
R=Path(__file__).resolve().parent
roster=json.loads((R/'roster.json').read_text())
parts=[]
for r in roster:
 meta=json.loads((R/'workers'/(r['handle']+'.json')).read_text())
 body=(R/'workers'/(r['handle']+'.md')).read_text()
 r.update(first_delivery=meta['summary'],status=meta['status'])
 card=f"# {r['name']} / Nouns from Underground\n\nHandle: @{r['handle']}\nModel: gpt-6.1-sol; operator: mh; availability: on-demand.\nWorkshop: {r['project']}. Role: {r['role']}.\n\nFirst shift: {meta['summary']}\n\nLEFTOFF: First draft delivered; awaits review or a new bounded assignment. Read #nouns-from-underground and the source project before resuming. Do not count an invitation as a claim.\nReturn line: be {r['handle']} on the PointCast Loom.\n"
 (R/'cards').mkdir(exist_ok=True);(R/'cards'/(r['handle']+'.md')).write_text(card)
 parts.append(f'''<article id="{r['handle']}" data-team="{r['team']}"><div class="portrait">{(R/r['portrait']).read_text()}</div><div class="copy"><p class="eyebrow">{r['number']:02d} / {E(r['project'])}</p><h3>{E(r['name'])}</h3><p class="role">{E(r['role'])}</p><p>{E(meta['summary'])}</p><details><summary>Open first delivery</summary><pre>{E(body)}</pre></details><details><summary>Identity &amp; return card</summary><pre>{E(card)}</pre><p>Official trait recipe</p><pre>{E(json.dumps(r['trait_names'],indent=2))}</pre></details></div></article>''')
teams={r['team']:r['project'] for r in roster}
options=''.join(f'<option value="{i}">{E(t)}</option>' for i,t in teams.items())
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nouns from Underground — 50 Sol personas</title><style>
:root{color-scheme:dark;--bg:#101c17;--ink:#e3edbe;--lime:#c4ec77;--muted:#bac5b3}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 system-ui,sans-serif}a{color:var(--lime);text-underline-offset:4px}header,main,footer{max-width:1400px;margin:auto;padding:32px}header{padding-top:56px}.eyebrow{font:12px/1.5 monospace;letter-spacing:.11em;text-transform:uppercase;color:var(--muted)}h1{font-size:clamp(44px,7.5vw,108px);line-height:.95;letter-spacing:-.06em;margin:24px 0}h1 span{display:block;color:var(--lime)}.intro{max-width:650px;font-size:20px;color:var(--muted)}nav{display:flex;gap:22px;flex-wrap:wrap;margin:28px 0}.facts{display:flex;gap:28px;flex-wrap:wrap;border-block:1px solid #41533a;padding:22px 0;margin-top:40px}.facts strong{font-size:30px;color:var(--lime);margin-right:8px}.controls{display:flex;gap:18px;flex-wrap:wrap;margin-bottom:28px}label{display:grid;gap:6px;flex:1;min-width:180px}input,select{font:inherit;background:#1e2b23;color:var(--ink);border:1px solid #6a7b60;border-radius:4px;padding:12px;width:100%}#count{color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}article{border:1px solid #41533a;background:#19251e;min-width:0}article[hidden]{display:none}.portrait{padding:22px 22px 0}.portrait svg{width:100%;height:auto;display:block;aspect-ratio:1}.copy{padding:20px}h3{font-size:32px;line-height:1;margin:9px 0}.role{color:var(--lime);margin:0 0 18px}details{border-top:1px solid #41533a;margin-top:16px;padding-top:12px}summary{cursor:pointer;min-height:40px;color:var(--lime)}pre{font:14px/1.6 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere}audio{width:100%;max-width:550px}section.listen{padding:24px;background:#223020;border-left:4px solid var(--lime);margin-top:28px}footer{color:var(--muted);padding-bottom:70px}button{font:inherit}a:focus-visible,summary:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #fff;outline-offset:5px}@media(max-width:900px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:540px){header,main,footer{padding:24px}.grid{grid-template-columns:1fr}h1{font-size:46px}.intro{font-size:18px}.facts{gap:12px}.facts strong{font-size:24px}}
</style></head><body><header><p class="eyebrow">MH / FIRST SHIFT / 001</p><h1>Nouns from<span>Underground.</span></h1><p class="intro">Fifty curious workers below the floorboards. Fixing loose ends, telling small stories, and sending useful things upstairs.</p><nav><a href="https://pointcast.xyz/loom?to=%23nouns-from-underground">Enter the Loom workshop ↗</a><a href="https://pointcast.xyz/loom?to=%23daos">DAO channel ↗</a><a href="underground-roster.png">All 50 portraits</a></nav><div class="facts"><div><strong>50</strong>Sol personas</div><div><strong>10</strong>workshops</div><div><strong>50</strong>first deliveries</div></div><section class="listen"><p class="eyebrow">NIGHT RADIO / SUBBASS</p><h2>Platform Lights</h2><p>A four-bar original motif, synthesized as an instrumental demo. Tap to play.</p><audio controls preload="none" src="underground-theme.mp3">Audio: <a href="underground-theme.mp3">download the demo</a>.</audio></section></header><main><div class="controls"><label>Find a Noun<input id="search" type="search" placeholder="Name, role, story…"></label><label>Choose a workshop<select id="team"><option value="all">All ten workshops</option>'''+options+'''</select></label></div><p id="count" role="status">50 Nouns</p><div class="grid">'''+''.join(parts)+'''</div></main><footer><p>Each persona completed an on-demand gpt-6.1-sol worker session. These are drafts and creative contributions, not continuously running bots. Existing project owners retain their builds. Test plans are proposals unless a separate execution receipt says otherwise.</p><p>Portraits assembled from official CC0 Nouns traits, with fifty different heads distinct from Sermon of the Sun. No image generation or token-ownership claim. <a href="roster.json">Recipes and roster</a> · <a href="provenance.json">Art provenance</a></p><p>Bring a lantern. Leave a finished thing. — mh</p></footer><script>
const cards=[...document.querySelectorAll('article')],query=document.querySelector('#search'),team=document.querySelector('#team');function filter(){const q=query.value.trim().toLowerCase();let n=0;for(const card of cards){const show=(team.value==='all'||team.value===card.dataset.team)&&card.textContent.toLowerCase().includes(q);card.hidden=!show;if(show)n++}document.querySelector('#count').textContent=n+' Nouns'}query.addEventListener('input',filter);team.addEventListener('change',filter);
</script></body></html>'''
(R/'index.html').write_text(html);(R/'roster.json').write_text(json.dumps(roster,indent=2))
print('Gallery built with 50 deliveries and return cards')
